import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;

public class Main {
  public static void main(String[] args) throws Exception {
      Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/mibase", "user", "pass");

      String sql = "UPDATE clientes SET direccion = ? WHERE direccion = ?";
      PreparedStatement pstmt = conn.prepareStatement(sql);

      // En Java debes inyectar cada placeholder por su índice 1-based:
      pstmt.setString(1, "Canyon 123"); // El SET
      pstmt.setString(2, "Valley 345"); // El WHERE

      int afectadas = pstmt.executeUpdate();
      System.out.println(afectadas + " registro(s) actualizado(s)");
  }
}
